func moodFor(_ value: String) -> String {
    let lower = value.lowercased()
    if lower.contains("calm") || lower.contains("gentle") || lower.contains("peace") { return "Calm" }
    if lower.contains("hope") || lower.contains("bright") || lower.contains("sun") { return "Hopeful" }
    if lower.contains("sad") || lower.contains("rain") || lower.contains("lonely") { return "Tender" }
    if lower.contains("run") || lower.contains("dance") || lower.contains("drive") { return "Energized" }
    return "Open"
}

